TEMPLATES = {
    'base.html': '<!DOCTYPE html>\n<html lang="id">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{% block title %}F3{% endblock %}</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Work+Sans:wght@400;500;600&display=swap" rel="stylesheet">\n    <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body>\n    <header>\n        <div class="wrap">\n            <nav>\n                <a href="{{ url_for(\'public.beranda\') }}" class="brand">\n                    <svg width="26" height="26" viewBox="0 0 26 26" fill="none">\n                        <circle cx="13" cy="13" r="12" stroke="#7B1F2B" stroke-width="1.4"/>\n                        <path d="M6 13c2-3 4-3 6 0s4 3 6 0" stroke="#4A2330" stroke-width="1.4" fill="none" stroke-linecap="round"/>\n                    </svg>\n                    F3\n                </a>\n                <button class="nav-toggle" id="navToggle" aria-label="Buka menu">\n                    <svg width="22" height="22" viewBox="0 0 22 22" fill="none"><path d="M2 6h18M2 11h18M2 16h18" stroke="#4A2330" stroke-width="1.6" stroke-linecap="round"/></svg>\n                </button>\n                <ul class="nav-links" id="navMenu">\n                    <li><a href="{{ url_for(\'public.beranda\') }}" class="{{ \'active\' if request.path == \'/\' else \'\' }}">Beranda</a></li>\n                    <li><a href="{{ url_for(\'public.layanan\') }}" class="{{ \'active\' if request.path == \'/layanan\' else \'\' }}">Layanan</a></li>\n                    <li><a href="{{ url_for(\'public.galeri\') }}" class="{{ \'active\' if request.path == \'/galeri\' else \'\' }}">Galeri</a></li>\n                    <li><a href="{{ url_for(\'public.tentang\') }}" class="{{ \'active\' if request.path == \'/tentang\' else \'\' }}">Tentang</a></li>\n                    <li><a href="{{ url_for(\'public.kontak\') }}" class="{{ \'active\' if request.path == \'/kontak\' else \'\' }}">Kontak</a></li>\n                    <li><a href="{{ url_for(\'public.pesan\') }}" class="nav-cta">Pesan sekarang</a></li>\n                </ul>\n            </nav>\n        </div>\n    </header>\n\n    <main>\n        {% with messages = get_flashed_messages(with_categories=true) %}\n            {% if messages %}\n                <div class="wrap flash-container">\n                    {% for category, message in messages %}\n                        <div class="flash flash-{{ category }}">{{ message }}</div>\n                    {% endfor %}\n                </div>\n            {% endif %}\n        {% endwith %}\n\n        {% block content %}{% endblock %}\n    </main>\n\n    <footer id="kontak">\n        <div class="wrap">\n            <div class="footer-grid">\n                <div>\n                    <div class="footer-brand">F3</div>\n                    Jl. Contoh Alamat No. 12, Jeneponto<br>\n                    Buka Senin&#8211;Sabtu, 09.00&#8211;17.00\n                </div>\n                <div class="more">\n                    <a href="https://wa.me/6281234567890" target="_blank" rel="noopener">WhatsApp: 0812-3456-7890</a>\n                    <a href="{{ url_for(\'public.kontak\') }}">Halaman kontak lengkap</a>\n                </div>\n                <div>\n                    &copy; 2026 F3.<br>Dibuat dengan bangga di Jeneponto.\n                </div>\n            </div>\n        </div>\n    </footer>\n\n    <a href="https://wa.me/6281234567890" class="wa-float" target="_blank" rel="noopener" aria-label="Chat WhatsApp">\n        <svg width="26" height="26" viewBox="0 0 16 16" fill="none"><path d="M2 14l1.5-4.2A6 6 0 1 1 6.3 12.6L2 14z" stroke="#F7F9FA" stroke-width="1.3"/></svg>\n    </a>\n\n    <div class="chat-widget">\n        <button class="chat-launcher" id="chatLauncher" aria-label="Chat dengan AI asisten">\n            <svg width="28" height="28" viewBox="0 0 16 16" fill="none"><path d="M3 2h10a1 1 0 0 1 1 1v7a1 1 0 0 1-1 1H7l-4 3v-3H3a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1z" stroke="#F7F9FA" stroke-width="1.3" stroke-linejoin="round"/></svg>\n            <span>Ask F3</span>\n        </button>\n\n        <div class="chat-panel" id="chatPanel" hidden>\n            <div class="chat-head">\n                <div class="chat-head-brand">\n                    <svg width="22" height="22" viewBox="0 0 26 26" fill="none">\n                        <circle cx="13" cy="13" r="12" stroke="#E0A72E" stroke-width="1.4"/>\n                        <path d="M6 13c2-3 4-3 6 0s4 3 6 0" stroke="#fff" stroke-width="1.4" fill="none" stroke-linecap="round"/>\n                    </svg>\n                    <div>\n                        <strong>Asisten F3</strong>\n                        <span>Balasan instan dari data toko</span>\n                    </div>\n                </div>\n                <button class="chat-close" id="chatClose" aria-label="Tutup chat">\n                    <svg width="18" height="18" viewBox="0 0 16 16" fill="none"><path d="M4 4l8 8M12 4l-8 8" stroke="#fff" stroke-width="1.4" stroke-linecap="round"/></svg>\n                </button>\n            </div>\n            <div class="chat-body" id="chatBody" aria-live="polite"></div>\n            <form class="chat-form" id="chatForm">\n                <input type="text" id="chatInput" placeholder="Tulis pertanyaan..." maxlength="2000" autocomplete="off">\n                <button type="submit" aria-label="Kirim">\n                    <svg width="18" height="18" viewBox="0 0 16 16" fill="none"><path d="M2 8l12-6-3.5 6L14 14 2 8z" stroke="#fff" stroke-width="1.3" stroke-linejoin="round"/></svg>\n                </button>\n            </form>\n        </div>\n    </div>\n\n    <script src="{{ url_for(\'static\', filename=\'js/main.js\') }}"></script>\n    <script src="{{ url_for(\'static\', filename=\'js/chat.js\') }}"></script>\n    {% block scripts %}{% endblock %}\n</body>\n</html>',
    'admin/base.html': '<!DOCTYPE html>\n<html lang="id">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{% block title %}Admin - F3{% endblock %}</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Work+Sans:wght@400;500;600&display=swap" rel="stylesheet">\n    <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body class="admin-body">\n    {% block body %}\n    <aside class="admin-sidebar" id="adminSidebar">\n        <a href="{{ url_for(\'admin.dashboard\') }}" class="brand sidebar-brand">\n            <svg width="24" height="24" viewBox="0 0 26 26" fill="none">\n                <circle cx="13" cy="13" r="12" stroke="#7B1F2B" stroke-width="1.4"/>\n                <path d="M6 13c2-3 4-3 6 0s4 3 6 0" stroke="#fff" stroke-width="1.4" fill="none" stroke-linecap="round"/>\n            </svg>\n            Admin Panel\n        </a>\n        <div class="sidebar-label">Menu</div>\n        <nav class="sidebar-nav">\n            <a href="{{ url_for(\'admin.dashboard\') }}" class="{{ \'active\' if request.endpoint == \'admin.dashboard\' else \'\' }}">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="1.5" y="1.5" width="5.5" height="5.5" rx="1" stroke="currentColor" stroke-width="1.4"/><rect x="9" y="1.5" width="5.5" height="5.5" rx="1" stroke="currentColor" stroke-width="1.4"/><rect x="1.5" y="9" width="5.5" height="5.5" rx="1" stroke="currentColor" stroke-width="1.4"/><rect x="9" y="9" width="5.5" height="5.5" rx="1" stroke="currentColor" stroke-width="1.4"/></svg>\n                Dashboard\n            </a>\n            <a href="{{ url_for(\'admin.pesanan_list\') }}" class="{{ \'active\' if request.endpoint in [\'admin.pesanan_list\', \'admin.pesanan_detail\'] else \'\' }}">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M5 1.5h6v4H5z" stroke="currentColor" stroke-width="1.4"/><path d="M2.5 4h10" stroke="currentColor" stroke-width="1.4"/><path d="M3 6v7.5a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V6" stroke="currentColor" stroke-width="1.4"/></svg>\n                Pesanan\n            </a>\n            <a href="{{ url_for(\'admin.layanan_manage\') }}" class="{{ \'active\' if request.endpoint in [\'admin.layanan_manage\', \'admin.layanan_edit\'] else \'\' }}">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M4 2L12 8M12 2L4 8" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><path d="M8 8l-4 5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>\n                Layanan\n            </a>\n            <a href="{{ url_for(\'admin.galeri_manage\') }}" class="{{ \'active\' if request.endpoint == \'admin.galeri_manage\' else \'\' }}">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="1.5" y="2" width="13" height="12" rx="1.5" stroke="currentColor" stroke-width="1.4"/><circle cx="5.5" cy="6" r="1.3" stroke="currentColor" stroke-width="1.4"/><path d="M2.5 12.5l3.5-3.5 2.5 2.5 2.5-2.5 2.5 2.5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>\n                Galeri\n            </a>\n            <a href="{{ url_for(\'admin.keluhan_list\') }}" class="{{ \'active\' if request.endpoint == \'admin.keluhan_list\' else \'\' }}">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M8 1.5a5.5 5.5 0 0 0-5.5 5.5c0 1.1.3 2.2.9 3.1l-.7 2.7 2.8-.7A5.5 5.5 0 1 0 8 1.5z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M5.5 6.5h5M5.5 9h3.5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>\n                Keluhan\n            </a>\n        </nav>\n        <div class="sidebar-foot">\n            <a href="{{ url_for(\'public.beranda\') }}" target="_blank" rel="noopener">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M6.5 9.5L14 2M14 2h-4M14 2v4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><path d="M13 9v3.5a1 1 0 0 1-1 1H3.5a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1H7" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>\n                Lihat Situs\n            </a>\n            <a href="{{ url_for(\'admin.logout\') }}" class="logout-link">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M6 2H3.5A1.5 1.5 0 0 0 2 3.5v9A1.5 1.5 0 0 0 3.5 14H6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><path d="M10 11.5L13.5 8 10 4.5M13.5 8H6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>\n                Logout\n            </a>\n        </div>\n    </aside>\n\n    <main class="admin-main">\n        <div class="admin-topbar">\n            <button class="admin-sidebar-toggle" id="adminSidebarToggle" aria-label="Buka menu">\n                <svg width="22" height="22" viewBox="0 0 22 22" fill="none"><path d="M2 6h18M2 11h18M2 16h18" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>\n            </button>\n            <span class="admin-topbar-title">Admin Panel</span>\n        </div>\n        {% with messages = get_flashed_messages(with_categories=true) %}\n            {% if messages %}\n                <div class="wrap flash-container">\n                    {% for category, message in messages %}\n                        <div class="flash flash-{{ category }}">{{ message }}</div>\n                    {% endfor %}\n                </div>\n            {% endif %}\n        {% endwith %}\n        {% block content %}{% endblock %}\n    </main>\n\n    {% endblock %}\n    <script src="{{ url_for(\'static\', filename=\'js/main.js\') }}"></script>\n    {% block scripts %}{% endblock %}\n</body>\n</html>',
    'admin/dashboard.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Dashboard - Admin F3{% endblock %}\n\n{% block content %}\n<div class="container admin-container">\n    <h1 class="admin-page-title">Dashboard</h1>\n    <p class="admin-page-sub">Selamat datang, {{ current_user.username }}!</p>\n\n    <div class="stat-grid">\n        <div class="stat-card stat-bar">\n            <i>Baru</i>\n            <div>\n                <h3>{{ pesanan_baru }}</h3>\n                <p>Pesanan Baru</p>\n            </div>\n        </div>\n        <div class="stat-card stat-progress">\n            <i>Proses</i>\n            <div>\n                <h3>{{ pesanan_dikerjakan }}</h3>\n                <p>Dikerjakan</p>\n            </div>\n        </div>\n        <div class="stat-card stat-done">\n            <i>Selesai</i>\n            <div>\n                <h3>{{ pesanan_selesai }}</h3>\n                <p>Selesai</p>\n            </div>\n        </div>\n        <div class="stat-card stat-cancel">\n            <i>Batal</i>\n            <div>\n                <h3>{{ pesanan_dibatalkan }}</h3>\n                <p>Dibatalkan</p>\n            </div>\n        </div>\n        <div class="stat-card stat-info">\n            <i>Layan</i>\n            <div>\n                <h3>{{ total_layanan }}</h3>\n                <p>Layanan</p>\n            </div>\n        </div>\n        <div class="stat-card stat-info">\n            <i>Foto</i>\n            <div>\n                <h3>{{ total_foto }}</h3>\n                <p>Foto Galeri</p>\n            </div>\n        </div>\n        <div class="stat-card stat-cancel">\n            <i>Keluh</i>\n            <div>\n                <h3>{{ total_keluhan }}</h3>\n                <p>Keluhan Customer</p>\n            </div>\n        </div>\n    </div>\n\n    <div class="panel">\n        <div class="panel-head">\n            <h2>Pesanan Terbaru</h2>\n            <a href="{{ url_for(\'admin.pesanan_list\') }}" class="btn btn-outline btn-sm">Lihat Semua</a>\n        </div>\n        <div class="table-responsive">\n            <table class="admin-table">\n                <thead>\n                    <tr>\n                        <th>Pelanggan</th>\n                        <th>No. WA</th>\n                        <th>Ukuran</th>\n                        <th>Tanggal Jadi</th>\n                        <th>Status</th>\n                        <th>Aksi</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    {% for p in recent %}\n                    <tr>\n                        <td>{{ p.nama_pelanggan }}</td>\n                        <td>{{ p.no_wa }}</td>\n                        <td>{{ p.ukuran }}</td>\n                        <td>{{ p.tanggal_jadi_diinginkan }}</td>\n                        <td><span class="badge badge-{{ p.status }}">{{ status_label[p.status] if p.status in status_label else p.status }}</span></td>\n                        <td><a href="{{ url_for(\'admin.pesanan_detail\', pesanan_id=p._id) }}" class="btn btn-info btn-xs">Detail</a></td>\n                    </tr>\n                    {% else %}\n                    <tr><td colspan="6" class="empty-cell">Belum ada pesanan.</td></tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n\n    <div class="quick-actions">\n        <a href="{{ url_for(\'public.pesan\') }}" target="_blank" class="btn btn-primary">Form Pemesanan</a>\n        <a href="{{ url_for(\'admin.layanan_manage\') }}" class="btn btn-outline">Kelola Layanan</a>\n        <a href="{{ url_for(\'admin.galeri_manage\') }}" class="btn btn-outline">Kelola Galeri</a>\n    </div>\n</div>\n{% endblock %}',
    'admin/galeri.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Galeri - Admin F3{% endblock %}\n\n{% block content %}\n<div class="container admin-container">\n    <h1 class="admin-page-title">Kelola Galeri</h1>\n    <p class="admin-page-sub">Upload dan hapus foto hasil jahitan</p>\n\n    <div class="panel">\n        <div class="panel-head"><h2>Upload Foto Baru</h2></div>\n        <form method="POST" action="{{ url_for(\'admin.galeri_manage\') }}" enctype="multipart/form-data" class="order-form">\n            <input type="hidden" name="action" value="upload">\n            <div class="form-row">\n                <div class="form-group">\n                    <label for="foto">File Foto <span class="req">*</span></label>\n                    <input type="file" id="foto" name="foto" accept="image/*" required>\n                </div>\n                <div class="form-group">\n                    <label for="keterangan">Keterangan (Opsional)</label>\n                    <input type="text" id="keterangan" name="keterangan" placeholder="Contoh: Gaun pesta custom">\n                </div>\n            </div>\n            <button type="submit" class="btn btn-primary">Upload Foto</button>\n        </form>\n    </div>\n\n    <div class="panel">\n        <div class="panel-head"><h2>Foto Galeri ({{ galeri|length }})</h2></div>\n        <div class="admin-gallery-grid">\n            {% for foto in galeri %}\n            <div class="admin-gallery-item">\n                <img src="{{ foto.url_foto }}" alt="{{ foto.keterangan or \'Foto galeri\' }}" loading="lazy">\n                <div class="admin-gallery-info">\n                    <p>{{ foto.keterangan or \'Tanpa keterangan\' }}</p>\n                    <form method="POST" action="{{ url_for(\'admin.galeri_manage\') }}" onsubmit="return confirm(\'Yakin ingin menghapus foto ini?\');">\n                        <input type="hidden" name="action" value="delete">\n                        <input type="hidden" name="foto_id" value="{{ foto._id }}">\n                        <button type="submit" class="btn btn-danger btn-xs">Hapus</button>\n                    </form>\n                </div>\n            </div>\n            {% else %}\n            <div class="empty-state full">\n                <p>Belum ada foto galeri.</p>\n            </div>\n            {% endfor %}\n        </div>\n    </div>\n</div>\n{% endblock %}',
    'admin/keluhan.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Keluhan Customer - Admin F3{% endblock %}\n\n{% block content %}\n<div class="container admin-container">\n    <div class="page-head-row">\n        <div>\n            <h1 class="admin-page-title">Keluhan Customer</h1>\n            <p class="admin-page-sub">Keluhan/komplain dari chatbot AI yang perlu ditindaklanjuti</p>\n        </div>\n        <a href="{{ url_for(\'public.beranda\') }}#kontak" target="_blank" class="btn btn-outline btn-sm">Lihat Kontak</a>\n    </div>\n\n    <div class="panel">\n        <div class="table-responsive">\n            <table class="admin-table">\n                <thead>\n                    <tr>\n                        <th>Waktu</th>\n                        <th>Nama</th>\n                        <th>No. WA</th>\n                        <th>Pesan Customer</th>\n                        <th>Balasan AI / Catatan</th>\n                        <th>Provider</th>\n                        <th>Aksi</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    {% for k in keluhan %}\n                    <tr>\n                        <td>{{ k.created_at.strftime(\'%d/%m/%Y %H:%M\') if k.created_at else \'-\' }}</td>\n                        <td>{{ k.nama or \'-\' }}</td>\n                        <td>{{ k.no_wa or \'-\' }}</td>\n                        <td class="desc-cell">{{ k.message }}</td>\n                        <td class="desc-cell">{{ k.reply }}</td>\n                        <td>{{ k.provider or \'-\' }}</td>\n                        <td>\n                            <div class="btn-row" style="gap:6px;">\n                                {% if k.no_wa %}\n                                <a href="https://wa.me/{{ k.no_wa }}?text=Halo,%20saya%20dari%20F3.%20Admin" target="_blank" rel="noopener" class="btn btn-wa btn-xs">Balas WA</a>\n                                {% endif %}\n                                <form action="{{ url_for(\'admin.keluhan_list\') }}" method="POST" style="display:inline;">\n                                    <input type="hidden" name="action" value="delete">\n                                    <input type="hidden" name="log_id" value="{{ k._id }}">\n                                    <button type="submit" class="btn btn-danger btn-xs">Hapus</button>\n                                </form>\n                            </div>\n                        </td>\n                    </tr>\n                    {% else %}\n                    <tr><td colspan="7" class="empty-cell">Belum ada keluhan masuk.</td></tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n{% endblock %}',
    'admin/layanan.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Layanan - Admin F3{% endblock %}\n\n{% block content %}\n<div class="container admin-container">\n    <h1 class="admin-page-title">Kelola Layanan</h1>\n    <p class="admin-page-sub">Tambah, edit, dan hapus daftar layanan</p>\n\n    <div class="panel">\n        <div class="panel-head"><h2>Tambah Layanan Baru</h2></div>\n        <form method="POST" action="{{ url_for(\'admin.layanan_manage\') }}" class="order-form">\n            <div class="form-row">\n                <div class="form-group">\n                    <label for="nama_jasa">Nama Jasa <span class="req">*</span></label>\n                    <input type="text" id="nama_jasa" name="nama_jasa" required placeholder="Contoh: Jahit Kebaya">\n                </div>\n                <div class="form-group">\n                    <label for="kategori">Kategori <span class="req">*</span></label>\n                    <select id="kategori" name="kategori" required>\n                        <option value="custom">Custom</option>\n                        <option value="permak">Permak</option>\n                        <option value="seragam">Seragam</option>\n                        <option value="lainnya">Lainnya</option>\n                    </select>\n                </div>\n                <div class="form-group">\n                    <label for="harga_kisaran">Harga Kisaran <span class="req">*</span></label>\n                    <input type="text" id="harga_kisaran" name="harga_kisaran" required placeholder="Contoh: Rp 150.000 - Rp 300.000">\n                </div>\n            </div>\n            <div class="form-group">\n                <label for="deskripsi">Deskripsi</label>\n                <textarea id="deskripsi" name="deskripsi" rows="3" placeholder="Deskripsi singkat tentang layanan"></textarea>\n            </div>\n            <div class="form-group checkbox-group">\n                <label class="checkbox-label">\n                    <input type="checkbox" name="aktif" checked> Aktif ditampilkan di situs\n                </label>\n            </div>\n            <button type="submit" class="btn btn-primary">Tambah Layanan</button>\n        </form>\n    </div>\n\n    <div class="panel">\n        <div class="panel-head"><h2>Daftar Layanan</h2></div>\n        <div class="table-responsive">\n            <table class="admin-table">\n                <thead>\n                    <tr>\n                        <th>Nama Jasa</th>\n                        <th>Kategori</th>\n                        <th>Harga</th>\n                        <th>Deskripsi</th>\n                        <th>Status</th>\n                        <th>Aksi</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    {% for l in layanan %}\n                    <tr>\n                        <td>{{ l.nama_jasa }}</td>\n                        <td><span class="badge badge-kategori">{{ l.kategori }}</span></td>\n                        <td>{{ l.harga_kisaran }}</td>\n                        <td class="desc-cell">{{ l.deskripsi }}</td>\n                        <td>\n                            {% if l.aktif %}\n                            <span class="badge badge-selesai">Aktif</span>\n                            {% else %}\n                            <span class="badge badge-dibatalkan">Nonaktif</span>\n                            {% endif %}\n                        </td>\n                        <td>\n                            <button class="btn btn-info btn-xs" onclick="toggleEdit(\'{{ l._id }}\')">Edit</button>\n                        </td>\n                    </tr>\n                    <tr id="edit-row-{{ l._id }}" class="edit-row" style="display:none;">\n                        <td colspan="6">\n                            <form method="POST" action="{{ url_for(\'admin.layanan_edit\', layanan_id=l._id) }}" class="order-form edit-form">\n                                <input type="hidden" name="action" value="update">\n                                <div class="form-row">\n                                    <div class="form-group">\n                                        <label>Nama Jasa *</label>\n                                        <input type="text" name="nama_jasa" value="{{ l.nama_jasa }}" required>\n                                    </div>\n                                    <div class="form-group">\n                                        <label>Kategori *</label>\n                                        <select name="kategori" required>\n                                            {% for k in [\'custom\', \'permak\', \'seragam\', \'lainnya\'] %}\n                                            <option value="{{ k }}" {{ \'selected\' if l.kategori == k else \'\' }}>{{ k|capitalize }}</option>\n                                            {% endfor %}\n                                        </select>\n                                    </div>\n                                    <div class="form-group">\n                                        <label>Harga Kisaran *</label>\n                                        <input type="text" name="harga_kisaran" value="{{ l.harga_kisaran }}" required>\n                                    </div>\n                                </div>\n                                <div class="form-group">\n                                    <label>Deskripsi</label>\n                                    <textarea name="deskripsi" rows="2">{{ l.deskripsi }}</textarea>\n                                </div>\n                                <div class="form-group checkbox-group">\n                                    <label class="checkbox-label">\n                                        <input type="checkbox" name="aktif" {{ \'checked\' if l.aktif else \'\' }}> Aktif\n                                    </label>\n                                </div>\n                                <div class="btn-row">\n                                    <button type="submit" class="btn btn-success btn-sm">Simpan</button>\n                                    <button type="button" class="btn btn-outline btn-sm" onclick="toggleEdit(\'{{ l._id }}\')">Batal</button>\n                                </div>\n                            </form>\n                            <form method="POST" action="{{ url_for(\'admin.layanan_edit\', layanan_id=l._id) }}" class="inline-delete" onsubmit="return confirm(\'Yakin ingin menghapus layanan ini?\');">\n                                <input type="hidden" name="action" value="delete">\n                                <button type="submit" class="btn btn-danger btn-sm">Hapus</button>\n                            </form>\n                        </td>\n                    </tr>\n                    {% else %}\n                    <tr><td colspan="6" class="empty-cell">Belum ada layanan.</td></tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction toggleEdit(id) {\n    var row = document.getElementById(\'edit-row-\' + id);\n    if (row) {\n        row.style.display = row.style.display === \'none\' ? \'\' : \'none\';\n    }\n}\n</script>\n{% endblock %}',
    'admin/login.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Login Admin - F3{% endblock %}\n\n{% block body %}\n<section class="admin-login-page">\n    <div class="admin-login-box">\n        <a href="{{ url_for(\'public.beranda\') }}" class="brand admin-login-brand">\n            <svg width="26" height="26" viewBox="0 0 26 26" fill="none">\n                <circle cx="13" cy="13" r="12" stroke="#7B1F2B" stroke-width="1.4"/>\n                <path d="M6 13c2-3 4-3 6 0s4 3 6 0" stroke="#4A2330" stroke-width="1.4" fill="none" stroke-linecap="round"/>\n            </svg>\n            F3\n        </a>\n        <h1>Admin Login</h1>\n        <p class="admin-login-sub">Masuk untuk mengelola situs</p>\n\n        {% if error %}\n        <div class="form-error">{{ error }}</div>\n        {% endif %}\n        {% with messages = get_flashed_messages(with_categories=true) %}\n            {% if messages %}\n                {% for category, message in messages %}\n                    <div class="flash flash-{{ category }}">{{ message }}</div>\n                {% endfor %}\n            {% endif %}\n        {% endwith %}\n\n        <form method="POST" action="{{ url_for(\'admin.login\') }}" class="order-form">\n            <div class="form-group">\n                <label for="username">Username</label>\n                <input type="text" id="username" name="username" required placeholder="Masukkan username" autofocus>\n            </div>\n            <div class="form-group">\n                <label for="password">Password</label>\n                <input type="password" id="password" name="password" required placeholder="Masukkan password">\n            </div>\n            <button type="submit" class="btn btn-primary btn-block">Login</button>\n        </form>\n        <p class="admin-login-back"><a href="{{ url_for(\'public.beranda\') }}">&larr; Kembali ke situs</a></p>\n    </div>\n</section>\n{% endblock %}',
    'admin/pesanan.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Pesanan - Admin F3{% endblock %}\n\n{% block content %}\n<div class="container admin-container">\n    <h1 class="admin-page-title">Daftar Pesanan</h1>\n    <p class="admin-page-sub">Kelola semua pesanan pelanggan</p>\n\n    <div class="filter-tabs">\n        <a href="{{ url_for(\'admin.pesanan_list\') }}" class="filter-tab {{ \'active\' if not status else \'\' }}">Semua</a>\n        {% for key, label in status_label.items() %}\n        <a href="{{ url_for(\'admin.pesanan_list\', status=key) }}" class="filter-tab {{ \'active\' if status == key else \'\' }}">{{ label }}</a>\n        {% endfor %}\n    </div>\n\n    <div class="panel">\n        <div class="table-responsive">\n            <table class="admin-table">\n                <thead>\n                    <tr>\n                        <th>Pelanggan</th>\n                        <th>No. WA</th>\n                        <th>Layanan</th>\n                        <th>Ukuran</th>\n                        <th>Tanggal Jadi</th>\n                        <th>Status</th>\n                        <th>Dibuat</th>\n                        <th>Aksi</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    {% for p in pesanan %}\n                    {% set lay = layanan_map.get(p.layanan_id|string) %}\n                    <tr>\n                        <td>{{ p.nama_pelanggan }}</td>\n                        <td>{{ p.no_wa }}</td>\n                        <td>{{ lay.nama_jasa if lay else \'-\' }}</td>\n                        <td>{{ p.ukuran }}</td>\n                        <td>{{ p.tanggal_jadi_diinginkan }}</td>\n                        <td><span class="badge badge-{{ p.status }}">{{ status_label[p.status] if p.status in status_label else p.status }}</span></td>\n                        <td>{{ p.created_at.strftime(\'%d/%m/%Y %H:%M\') if p.created_at else \'-\' }}</td>\n                        <td><a href="{{ url_for(\'admin.pesanan_detail\', pesanan_id=p._id) }}" class="btn btn-info btn-xs">Detail</a></td>\n                    </tr>\n                    {% else %}\n                    <tr><td colspan="8" class="empty-cell">Belum ada pesanan.</td></tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n{% endblock %}',
    'admin/pesanan_detail.html': '{% extends \'admin/base.html\' %}\n\n{% block title %}Detail Pesanan - Admin F3{% endblock %}\n\n{% block content %}\n<div class="container admin-container">\n    <div class="page-head-row">\n        <div>\n            <h1 class="admin-page-title">Detail Pesanan</h1>\n            <p class="admin-page-sub">Pesanan dari {{ pesanan.nama_pelanggan }}</p>\n        </div>\n        <a href="{{ url_for(\'admin.pesanan_list\') }}" class="btn btn-outline btn-sm">&larr; Kembali</a>\n    </div>\n\n    <div class="detail-grid">\n        <div class="panel">\n            <div class="panel-head"><h2>Informasi Pelanggan</h2></div>\n            <div class="detail-list">\n                <div class="detail-row">\n                    <span class="detail-label">Nama</span>\n                    <span class="detail-value">{{ pesanan.nama_pelanggan }}</span>\n                </div>\n                <div class="detail-row">\n                    <span class="detail-label">No. WA</span>\n                    <span class="detail-value">\n                        {{ pesanan.no_wa }}\n                        <a href="https://wa.me/{{ pesanan.no_wa }}" target="_blank" rel="noopener" class="btn btn-wa btn-xs">Chat</a>\n                    </span>\n                </div>\n            </div>\n        </div>\n\n        <div class="panel">\n            <div class="panel-head"><h2>Detail Pemesanan</h2></div>\n            <div class="detail-list">\n                <div class="detail-row">\n                    <span class="detail-label">Layanan</span>\n                    <span class="detail-value">{{ layanan.nama_jasa if layanan else \'-\' }}</span>\n                </div>\n                <div class="detail-row">\n                    <span class="detail-label">Harga Kisaran</span>\n                    <span class="detail-value">{{ layanan.harga_kisaran if layanan else \'-\' }}</span>\n                </div>\n                <div class="detail-row">\n                    <span class="detail-label">Ukuran</span>\n                    <span class="detail-value">{{ pesanan.ukuran }}</span>\n                </div>\n                <div class="detail-row">\n                    <span class="detail-label">Tanggal Jadi Diinginkan</span>\n                    <span class="detail-value">{{ pesanan.tanggal_jadi_diinginkan }}</span>\n                </div>\n                <div class="detail-row">\n                    <span class="detail-label">Dibuat</span>\n                    <span class="detail-value">{{ pesanan.created_at.strftime(\'%d/%m/%Y %H:%M\') if pesanan.created_at else \'-\' }}</span>\n                </div>\n                <div class="detail-row">\n                    <span class="detail-label">Status</span>\n                    <span class="detail-value"><span class="badge badge-{{ pesanan.status }}">{{ status_label[pesanan.status] if pesanan.status in status_label else pesanan.status }}</span></span>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    {% if pesanan.catatan %}\n    <div class="panel">\n        <div class="panel-head"><h2>Catatan Pelanggan</h2></div>\n        <p class="detail-note">{{ pesanan.catatan }}</p>\n    </div>\n    {% endif %}\n\n    <div class="panel">\n        <div class="panel-head"><h2>Update Status</h2></div>\n        <form method="POST" action="{{ url_for(\'admin.pesanan_detail\', pesanan_id=pesanan._id) }}" class="status-form">\n            <input type="hidden" name="action" value="update_status">\n            <select name="status" required>\n                {% for key, label in status_label.items() %}\n                <option value="{{ key }}" {{ \'selected\' if pesanan.status == key else \'\' }}>{{ label }}</option>\n                {% endfor %}\n            </select>\n            <button type="submit" class="btn btn-primary">Perbarui Status</button>\n        </form>\n    </div>\n\n    <div class="danger-zone">\n        <form method="POST" action="{{ url_for(\'admin.pesanan_detail\', pesanan_id=pesanan._id) }}" onsubmit="return confirm(\'Yakin ingin menghapus pesanan ini?\');">\n            <input type="hidden" name="action" value="delete">\n            <button type="submit" class="btn btn-danger btn-sm">Hapus Pesanan</button>\n        </form>\n    </div>\n</div>\n{% endblock %}',
    'public/beranda.html': '{% extends \'base.html\' %}\n\n{% block title %}Beranda - F3{% endblock %}\n\n{% block content %}\n<section class="hero">\n    <div class="wrap">\n        <div class="eyebrow-line"><span class="dash"></span> Jahit rumahan, sejak 2008 · Jeneponto</div>\n        <h1>Setiap jahitan<br>dikerjakan <span class="accent">seolah untuk keluarga sendiri</span></h1>\n        <p class="lede">Jahit custom, permak, dan seragam dengan ukuran yang pas dan hasil rapi — dikerjakan langsung oleh Ibu Sumarni, ditemani secangkir kopi dan mesin jahit yang sudah menemani ratusan pelanggan.</p>\n        <div class="hero-actions">\n            <a href="{{ url_for(\'public.pesan\') }}" class="btn btn-primary">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M2 14l1.5-4.2A6 6 0 1 1 6.3 12.6L2 14z" stroke="#4A2330" stroke-width="1.3"/></svg>\n                Chat via WhatsApp\n            </a>\n            <a href="{{ url_for(\'public.layanan\') }}" class="btn-secondary">Lihat layanan &amp; harga</a>\n        </div>\n        <div class="hero-stats">\n            <div><div class="num">15+</div><div class="lbl">tahun pengalaman</div></div>\n            <div><div class="num">400+</div><div class="lbl">jahitan selesai</div></div>\n            <div><div class="num">2&#8211;5 hari</div><div class="lbl">rata-rata pengerjaan</div></div>\n        </div>\n    </div>\n</section>\n\n<div class="trustline">\n    <div class="wrap">\n        <div><strong>Bahan sendiri atau bawa sendiri</strong> — kami sesuaikan</div>\n        <div><strong>Ukuran diambil langsung</strong> di rumah/toko</div>\n        <div><strong>Revisi gratis</strong> jika ukuran kurang pas</div>\n    </div>\n</div>\n\n<section class="section" id="layanan">\n    <div class="wrap">\n        <div class="section-head">\n            <h2>Layanan pilihan</h2>\n            <p>Beberapa layanan yang paling sering dipesan. Klik &ldquo;lihat semua layanan&rdquo; untuk daftar lengkap dan kisaran harga.</p>\n        </div>\n        <div class="services">\n            {% for item in layanan[:3] %}\n            <div class="service-card">\n                {% if loop.index == 1 %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><path d="M8 8l24 24M32 8L8 32" stroke="#7B1F2B" stroke-width="2" stroke-linecap="round"/></svg>\n                {% elif loop.index == 2 %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="14" stroke="#7B1F2B" stroke-width="2"/><path d="M20 12v8l6 4" stroke="#7B1F2B" stroke-width="2" stroke-linecap="round"/></svg>\n                {% else %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><rect x="9" y="9" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/><rect x="22" y="9" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/><rect x="9" y="22" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/><rect x="22" y="22" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/></svg>\n                {% endif %}\n                <h3>{{ item.nama_jasa }}</h3>\n                <p>{{ item.deskripsi }}</p>\n                <div class="price">{{ item.harga_kisaran }}</div>\n            </div>\n            {% else %}\n            <div class="service-card">Layanan sedang diperbarui.</div>\n            {% endfor %}\n        </div>\n        <div class="center-btn"><a href="{{ url_for(\'public.layanan\') }}" class="btn-secondary">Lihat semua layanan &amp; harga</a></div>\n    </div>\n</section>\n\n<section class="section section-tint" id="galeri">\n    <div class="wrap">\n        <div class="section-head">\n            <h2>Hasil jahitan kami</h2>\n            <p>Sebagian kecil dari jahitan yang sudah selesai dikerjakan.</p>\n        </div>\n        <div class="gallery-grid">\n            {% if galeri %}\n                {% for foto in galeri[:8] %}\n                <div class="gallery-item">\n                    <img src="{{ foto.url_foto }}" alt="{{ foto.keterangan or \'Hasil jahitan\' }}" loading="lazy">\n                    {% if foto.keterangan %}<span class="gcaption">{{ foto.keterangan }}</span>{% endif %}\n                </div>\n                {% endfor %}\n            {% else %}\n                <div class="gallery-item ph">Foto pelanggan 1</div>\n                <div class="gallery-item ph">Foto pelanggan 2</div>\n                <div class="gallery-item ph">Foto pelanggan 3</div>\n                <div class="gallery-item ph">Foto pelanggan 4</div>\n                <div class="gallery-item ph">Foto pelanggan 5</div>\n                <div class="gallery-item ph">Foto pelanggan 6</div>\n                <div class="gallery-item ph">Foto pelanggan 7</div>\n                <div class="gallery-item ph">Foto pelanggan 8</div>\n            {% endif %}\n        </div>\n        <div class="center-btn"><a href="{{ url_for(\'public.galeri\') }}" class="btn-secondary">Lihat galeri lengkap</a></div>\n    </div>\n</section>\n\n<section class="section" id="tentang">\n    <div class="wrap about">\n        <div class="about-visual">\n            <svg width="60%" viewBox="0 0 100 100" fill="none">\n                <circle cx="50" cy="35" r="18" stroke="#4A2330" stroke-width="2"/>\n                <path d="M20 90c0-20 13-32 30-32s30 12 30 32" stroke="#4A2330" stroke-width="2"/>\n            </svg>\n        </div>\n        <div>\n            <h2>Dikerjakan sendiri, bukan lewat perantara</h2>\n            <p>Toko ini dimulai dari mesin jahit di ruang tamu, melayani tetangga yang butuh permak celana sekolah. Sekarang sudah melayani ratusan pelanggan di sekitar Jeneponto — tapi caranya masih sama: diukur teliti, dikerjakan sabar, dan diselesaikan tepat waktu.</p>\n            <p>Setiap pesanan dikerjakan langsung, tanpa dialihkan ke penjahit lain, supaya kualitas dan waktu pengerjaannya bisa dipastikan sendiri.</p>\n            <div class="about-quote">"Yang penting pas di badan dan rapi jahitannya — itu baru selesai namanya."</div>\n        </div>\n    </div>\n</section>\n\n<section class="section section-tint">\n    <div class="wrap">\n        <div class="section-head">\n            <h2>Kata pelanggan</h2>\n        </div>\n        <div class="testimonials">\n            <div class="t-card">\n                <p>"Permak celana kerja langsung pas, cuma nunggu sehari. Harganya juga wajar."</p>\n                <div class="t-name">— Pelanggan, Panakkukang</div>\n            </div>\n            <div class="t-card">\n                <p>"Jahitan gamis untuk acara keluarga rapi banget, ukurannya pas tanpa perlu revisi."</p>\n                <div class="t-name">— Pelanggan, Biringkanaya</div>\n            </div>\n            <div class="t-card">\n                <p>"Pesan seragam untuk 20 orang, semuanya selesai tepat waktu dan seragam ukurannya."</p>\n                <div class="t-name">— Perwakilan sekolah, Jeneponto</div>\n            </div>\n        </div>\n    </div>\n</section>\n\n<section class="section" id="pesan">\n    <div class="wrap">\n        <div class="cta-band">\n            <h2>Siap dijahitkan? Chat dulu, tanpa perlu datang ke toko.</h2>\n            <a href="{{ url_for(\'public.pesan\') }}" class="btn btn-primary">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M2 14l1.5-4.2A6 6 0 1 1 6.3 12.6L2 14z" stroke="#4A2330" stroke-width="1.3"/></svg>\n                Chat WhatsApp: 0812-3456-7890\n            </a>\n        </div>\n    </div>\n</section>\n{% endblock %}\n',
    'public/galeri.html': '{% extends \'base.html\' %}\n\n{% block title %}Galeri - F3{% endblock %}\n\n{% block content %}\n<section class="page-hero">\n    <div class="wrap">\n        <div class="eyebrow-line"><span class="dash"></span> Portofolio</div>\n        <h1>Hasil jahitan kami</h1>\n        <p>Sebagian kecil dari jahitan yang sudah selesai dikerjakan untuk para pelanggan.</p>\n    </div>\n</section>\n\n<section class="section">\n    <div class="wrap">\n        <div class="gallery-grid large">\n            {% if galeri %}\n                {% for foto in galeri %}\n                <div class="gallery-item">\n                    <img src="{{ foto.url_foto }}" alt="{{ foto.keterangan or \'Hasil jahitan\' }}" loading="lazy">\n                    {% if foto.keterangan %}<span class="gcaption">{{ foto.keterangan }}</span>{% endif %}\n                </div>\n                {% endfor %}\n            {% else %}\n                <div class="empty-state">\n                    <svg width="44" height="44" viewBox="0 0 24 24" fill="none" style="display:block;margin:0 auto 12px;"><rect x="2" y="2" width="20" height="20" rx="3" stroke="#E0A72E" stroke-width="1.6"/><circle cx="9" cy="9" r="2" stroke="#E0A72E" stroke-width="1.6"/><path d="M3 19l6-6 4 4 3-3 5 5" stroke="#E0A72E" stroke-width="1.6"/></svg>\n                    <p>Belum ada foto galeri. Silakan kembali lagi nanti.</p>\n                </div>\n            {% endif %}\n        </div>\n    </div>\n</section>\n{% endblock %}',
    'public/kontak.html': '{% extends \'base.html\' %}\n\n{% block title %}Kontak - F3{% endblock %}\n\n{% block content %}\n<section class="page-hero">\n    <div class="wrap">\n        <div class="eyebrow-line"><span class="dash"></span> Di mana kami</div>\n        <h1>Hubungi kami</h1>\n        <p>Chat dulu saja biasanya lebih cepat — tapi kalau mau mampir, kami siap di tempat.</p>\n    </div>\n</section>\n\n<section class="section">\n    <div class="wrap">\n        <div class="cta-band" style="margin-bottom:48px;">\n            <div>\n                <h2>Chat langsung ke WhatsApp</h2>\n                <div style="color:rgba(245,239,227,.85);font-size:15px;margin-top:8px;">0812-3456-7890 · dibalas Senin&#8211;Sabtu, 09.00&#8211;17.00</div>\n            </div>\n            <a href="https://wa.me/6281234567890" target="_blank" rel="noopener" class="btn btn-primary">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M2 14l1.5-4.2A6 6 0 1 1 6.3 12.6L2 14z" stroke="#4A2330" stroke-width="1.3"/></svg>\n                Chat WhatsApp\n            </a>\n        </div>\n\n        <div class="services" style="grid-template-columns:repeat(3,1fr);">\n            <div class="service-card">\n                <h3>Alamat</h3>\n                <p>Jl. Contoh Alamat No. 12<br>Jeneponto, Sulawesi Selatan</p>\n            </div>\n            <div class="service-card">\n                <h3>Jam buka</h3>\n                <p>Senin&#8211;Sabtu: 09.00&#8211;17.00<br>Minggu: tutup</p>\n            </div>\n            <div class="service-card">\n                <h3>Instagram</h3>\n                <p>@jahitibuaminah<br>Update hasil jahitan di feed &amp; story</p>\n            </div>\n        </div>\n    </div>\n</section>\n\n<section class="section section-tint">\n    <div class="wrap">\n        <div class="section-head">\n            <h2>Peta lokasi</h2>\n        </div>\n        <div class="about-visual" style="aspect-ratio:16/6;max-width:100%;">\n            <div style="text-align:center;color:var(--ink-soft);font-size:15px;">\n                Tempatkan Google Maps Embed di sini<br>\n                <span style="font-size:13px;">(cari alamat toko Anda di Google Maps → Bagikan → Salin embed)</span>\n            </div>\n        </div>\n    </div>\n</section>\n{% endblock %}',
    'public/layanan.html': '{% extends \'base.html\' %}\n\n{% block title %}Layanan - F3{% endblock %}\n\n{% block content %}\n<section class="page-hero">\n    <div class="wrap">\n        <div class="eyebrow-line"><span class="dash"></span> Daftar jasa &amp; harga</div>\n        <h1>Layanan &amp; kisaran harga</h1>\n        <p>Dari baju custom, permak, sampai pesanan seragam dalam jumlah banyak — semua dikerjakan langsung, tanpa perantara.</p>\n    </div>\n</section>\n\n<section class="section">\n    <div class="wrap">\n        <div class="services">\n            {% for item in layanan %}\n            <div class="service-card">\n                {% if loop.index == 1 %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><path d="M8 8l24 24M32 8L8 32" stroke="#7B1F2B" stroke-width="2" stroke-linecap="round"/></svg>\n                {% elif loop.index == 2 %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="14" stroke="#7B1F2B" stroke-width="2"/><path d="M20 12v8l6 4" stroke="#7B1F2B" stroke-width="2" stroke-linecap="round"/></svg>\n                {% elif loop.index == 3 %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><rect x="9" y="9" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/><rect x="22" y="9" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/><rect x="9" y="22" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/><rect x="22" y="22" width="9" height="9" stroke="#7B1F2B" stroke-width="2"/></svg>\n                {% else %}\n                <svg class="icon" viewBox="0 0 40 40" fill="none"><path d="M8 8l24 24M32 8L8 32" stroke="#7B1F2B" stroke-width="2" stroke-linecap="round"/></svg>\n                {% endif %}\n                <h3>{{ item.nama_jasa }}</h3>\n                <p>{{ item.deskripsi }}</p>\n                <div class="price">{{ item.harga_kisaran }}</div>\n                <a href="{{ url_for(\'public.pesan\') }}" class="btn btn-primary btn-sm">Pesan layanan ini</a>\n            </div>\n            {% else %}\n            <div class="empty-state">Daftar layanan sedang diperbarui. Silakan kembali lagi nanti.</div>\n            {% endfor %}\n        </div>\n    </div>\n</section>\n\n<section class="section section-tint">\n    <div class="wrap">\n        <div class="cta-band">\n            <h2>Punya kebutuhan jahit spesial?</h2>\n            <a href="{{ url_for(\'public.kontak\') }}" class="btn btn-primary">Hubungi kami</a>\n        </div>\n    </div>\n</section>\n{% endblock %}',
    'public/pesan.html': '{% extends \'base.html\' %}\n\n{% block title %}Pesan - F3{% endblock %}\n\n{% block content %}\n<section class="page-hero">\n    <div class="wrap">\n        <div class="eyebrow-line"><span class="dash"></span> Mulai pesanan</div>\n        <h1>Form pemesanan</h1>\n        <p>Isi form di bawah, nanti kami balas lewat WhatsApp untuk konfirmasi ukuran dan jadwal.</p>\n    </div>\n</section>\n\n<section class="section">\n    <div class="wrap form-wrap">\n        {% if submitted %}\n        <div class="success-box">\n            <svg width="54" height="54" viewBox="0 0 24 24" fill="none" style="display:block;margin:0 auto 16px;"><circle cx="12" cy="12" r="10" stroke="#7B1F2B" stroke-width="1.6"/><path d="M7 12l3 3 7-7" stroke="#7B1F2B" stroke-width="1.8" stroke-linecap="round"/></svg>\n            <h2>Pemesanan berhasil!</h2>\n            <p>Terima kasih, pesanan Anda sudah kami terima. Kami akan menghubungi Anda lewat WhatsApp untuk konfirmasi.</p>\n            {% if wa_link %}\n            <p class="wa-note">Agar lebih cepat, boleh langsung konfirmasi lewat WhatsApp:</p>\n            <a href="{{ wa_link }}" target="_blank" rel="noopener" class="btn btn-wa">Konfirmasi via WhatsApp</a>\n            {% endif %}\n            <br>\n            <a href="{{ url_for(\'public.beranda\') }}" class="btn btn-outline">Kembali ke beranda</a>\n        </div>\n        {% else %}\n        {% if error %}\n        <div class="form-error">{{ error }}</div>\n        {% endif %}\n\n        <form method="POST" action="{{ url_for(\'public.pesan\') }}" class="order-form">\n            <div class="form-row">\n                <div class="form-group">\n                    <label for="nama_pelanggan">Nama lengkap <span class="req">*</span></label>\n                    <input type="text" id="nama_pelanggan" name="nama_pelanggan" required placeholder="Nama Anda">\n                </div>\n                <div class="form-group">\n                    <label for="no_wa">No. WhatsApp <span class="req">*</span></label>\n                    <input type="tel" id="no_wa" name="no_wa" required placeholder="08xxxxxxxxxx">\n                </div>\n            </div>\n            <div class="form-row">\n                <div class="form-group">\n                    <label for="layanan_id">Pilih layanan <span class="req">*</span></label>\n                    <select id="layanan_id" name="layanan_id" required>\n                        <option value="">-- Pilih layanan --</option>\n                        {% for item in layanan %}\n                        <option value="{{ item._id }}">{{ item.nama_jasa }} ({{ item.harga_kisaran }})</option>\n                        {% endfor %}\n                    </select>\n                </div>\n                <div class="form-group">\n                    <label for="ukuran">Ukuran <span class="req">*</span></label>\n                    <input type="text" id="ukuran" name="ukuran" required placeholder="M, L, XL / 90, 95, 100">\n                </div>\n            </div>\n            <div class="form-group">\n                <label for="tanggal_jadi">Tanggal jadi diinginkan <span class="req">*</span></label>\n                <input type="date" id="tanggal_jadi" name="tanggal_jadi" required>\n            </div>\n            <div class="form-group">\n                <label for="catatan">Catatan (opsional)</label>\n                <textarea id="catatan" name="catatan" rows="4" placeholder="Model, bahan, warna, referensi, dll."></textarea>\n            </div>\n            <button type="submit" class="btn btn-primary btn-block">Kirim pemesanan</button>\n        </form>\n        {% endif %}\n    </div>\n</section>\n{% endblock %}',
    'public/tentang.html': '{% extends \'base.html\' %}\n\n{% block title %}Tentang - F3{% endblock %}\n\n{% block content %}\n<section class="page-hero">\n    <div class="wrap">\n        <div class="eyebrow-line"><span class="dash"></span> Cerita kami</div>\n        <h1>Dikerjakan sendiri, bukan lewat perantara</h1>\n        <p>Dari mesin jahit di ruang tamu hingga ratusan pelanggan di sekitar Jeneponto — caranya masih sama.</p>\n    </div>\n</section>\n\n<section class="section">\n    <div class="wrap about">\n        <div class="about-visual">\n            <svg width="60%" viewBox="0 0 100 100" fill="none">\n                <circle cx="50" cy="35" r="18" stroke="#4A2330" stroke-width="2"/>\n                <path d="M20 90c0-20 13-32 30-32s30 12 30 32" stroke="#4A2330" stroke-width="2"/>\n            </svg>\n        </div>\n        <div>\n            <h2>Berawal dari ruang tamu</h2>\n            <p>Toko ini dimulai dari mesin jahit di ruang tamu, melayani tetangga yang butuh permak celana sekolah. Sekarang sudah melayani ratusan pelanggan di sekitar Jeneponto — tapi caranya masih sama: diukur teliti, dikerjakan sabar, dan diselesaikan tepat waktu.</p>\n            <p>Setiap pesanan dikerjakan langsung, tanpa dialihkan ke penjahit lain, supaya kualitas dan waktu pengerjaannya bisa dipastikan sendiri.</p>\n            <div class="about-quote">"Yang penting pas di badan dan rapi jahitannya — itu baru selesai namanya."</div>\n        </div>\n    </div>\n</section>\n\n<section class="section section-tint">\n    <div class="wrap">\n        <div class="section-head">\n            <h2>Kenapa memilih kami?</h2>\n        </div>\n        <div class="testimonials">\n            <div class="t-card">\n                <h3 style="font-family:\'Work Sans\',sans-serif;font-size:18px;font-weight:600;margin-bottom:10px;">Bahan sesuaikan</h3>\n                <p>Bisa pakai bahan sendiri atau kami sediakan — dihitung transparan di awal.</p>\n            </div>\n            <div class="t-card">\n                <h3 style="font-family:\'Work Sans\',sans-serif;font-size:18px;font-weight:600;margin-bottom:10px;">Revisi gratis</h3>\n                <p>Jika ukuran kurang pas, kami perbaiki tanpa biaya tambahan sampai benar-benar pas.</p>\n            </div>\n            <div class="t-card">\n                <h3 style="font-family:\'Work Sans\',sans-serif;font-size:18px;font-weight:600;margin-bottom:10px;">Tepat waktu</h3>\n                <p>Pengerjaan rata-rata 2&#8211;5 hari dan diusahakan sesuai janji, apalagi untuk pesanan seragam.</p>\n            </div>\n        </div>\n    </div>\n</section>\n\n<section class="section">\n    <div class="wrap">\n        <div class="cta-band">\n            <h2>Mau pesan sesuatu? Yuk mulai dari chat.</h2>\n            <a href="{{ url_for(\'public.pesan\') }}" class="btn btn-primary">\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M2 14l1.5-4.2A6 6 0 1 1 6.3 12.6L2 14z" stroke="#4A2330" stroke-width="1.3"/></svg>\n                Pesan sekarang\n            </a>\n        </div>\n    </div>\n</section>\n{% endblock %}',
}
